import os

def get_list(n):
    my_list, cnt, st = [], 0, [False]*n*10
    for i in range(2, n+1):
        if not st[i]:
            my_list.append(i)
            cnt += 1
        for j in range(n):
            if my_list[j] * i > n: 
                break
            st[my_list[j] * i] = True

            if i % my_list[j] == 0: 
                break
    return my_list

primes=get_list(42)

def is_prime(n):
    if n == 2 or n == 3:
        return True

    if n < 2 or n % 2 == 0:
        return False

    bitsize = n.bit_length()
    if bitsize >= 1536:
        k = 3
    elif bitsize >= 1024:
        k = 4
    elif bitsize >= 512:
        k = 7
    else:
        k = 10

    s, d = 0, n - 1
    while d % 2 == 0:
        s, d = s + 1, d // 2

    for _ in range(k):
        a = randint(2, n - 2)
        x = pow(a, d, n)

        if x == 1 or x == n - 1:
            continue

        for _ in range(s - 1):
            x = pow(x, 2, n)
            if x == n - 1:
                break
        else:
            return False

    return True

def myPrime(bits):
    while True:
        n = 2
        while n.bit_length() < bits:
            n *= choice(primes)
        if is_prime(n + 1):
            return n + 1
        
